package ai.neargo.shop.unit;
import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import java.time.Instant;
import ai.neargo.shop.member.service.*;import ai.neargo.shop.member.dto.*;import ai.neargo.shop.paybridge.*;import ai.neargo.shop.paybridge.dto.StoredValueScopeViews.*;import ai.neargo.shop.payclient.*;import ai.neargo.shop.spi.entitlement.EntitlementContext;import ai.neargo.shop.spi.user.MemberIdentityFactsPort;import ai.neargo.shop.spi.storedvalue.StoredValueMerchantViews;import ai.neargo.shop.common.*;
class ScopedStoredValueMemberTest {
 final MemberScopeService members=mock(MemberScopeService.class);final MemberScopeQueryService queries=mock(MemberScopeQueryService.class);final MemberCodeResolveService codes=mock(MemberCodeResolveService.class);final StoredValueMerchantQueryAppService accounts=mock(StoredValueMerchantQueryAppService.class);final StoredValuePlanRechargeAppService direct=mock(StoredValuePlanRechargeAppService.class);final StoredValueMemberSelectionService legacy=mock(StoredValueMemberSelectionService.class);final EntitlementContext ctx=new EntitlementContext("MAIN","A","test","0".repeat(64));
 ScopedStoredValueMemberService service(){return new ScopedStoredValueMemberService(members,queries,codes,accounts,direct,legacy);}
 @Test void foreignMemberCannotIssueReferenceOrTouchPay(){when(members.require("MAIN","E1","S1","FOREIGN")).thenThrow(BizException.of(ErrorCode.NOT_FOUND));assertThatThrownBy(()->service().select(ctx,"E1","S1",new Source("MEMBER","FOREIGN",null,null),true)).isInstanceOf(BizException.class);verifyNoInteractions(accounts,codes,direct);}
 @Test void brandMemberSelectionOnlyQueriesCurrentStoreAndDoesNotCreateWallet(){var m=new MemberScopeModels.ScopeMember("MSM1","P1","BRAND","B1","S2","ACTIVE");when(members.require("MAIN","E1","S1","MSM1")).thenReturn(m);when(members.identity("MAIN","P1")).thenReturn(new MemberIdentityFactsPort.Identity("P1","U1","138****8000",true));when(queries.detail("MAIN","E1","S1","MSM1")).thenReturn(new MemberScopeModels.Summary("MSM1","顾客","138****8000","ACTIVE","S2","乙店",null));when(codes.selectScopedCustomer(any(),eq("MSM1"))).thenReturn(new MemberCodeViews.CustomerReference("cr1_test","顾客",Instant.now().plusSeconds(120)));when(accounts.directory(any(),eq("S1"),anyList(),anyString(),isNull(),eq(1))).thenReturn(new CursorPage<StoredValueMerchantViews.Account>(List.of(),null));var result=service().select(ctx,"E1","S1",new Source("MEMBER","MSM1",null,null),true);assertThat(result.selection().account()).isNull();assertThat(result.sourceStoreNo()).isEqualTo("S2");verify(accounts).directory(argThat(s->s.entityNo().equals("E1")),eq("S1"),anyList(),anyString(),isNull(),eq(1));verifyNoMoreInteractions(accounts);verify(direct).bindCustomer(ctx,"P1","U1");}
 @Test void noFinancialReadPermissionReturnsNoBalanceAndNeverCallsPayQueries(){when(queries.search("MAIN","E1","S1","A","138",null,20)).thenReturn(new MemberScopeModels.Page(List.of(new MemberScopeModels.Summary("MSM1","顾客","138****8000","LEAD","S2","乙店",null)),null));var result=service().candidates(ctx,"E1","S1","138",null,20,false);assertThat(result.items().getFirst().account()).isNull();verifyNoInteractions(accounts);}
}
